def describe(rows):
    a=np.array([[int(x) for x in r] for r in rows]); h,w=a.shape
    rr,cc=np.indices(a.shape); n=a.sum()
    return {'a':a,'h':h,'w':w,'n':n,'empty':h*w-n,'area':h*w,'dens':n/(h*w), 'hs':np.array_equal(a,a[::-1]),'vs':np.array_equal(a,a[:,::-1]),'r180':np.array_equal(a,np.rot90(a,2)),
            'rr':a.sum(axis=1).tolist(),'cc':a.sum(axis=0).tolist(), 'rows_nonzero':int((a.sum(1)>0).sum()), 'cols_nonzero':int((a.sum(0)>0).sum()),
            'top':a[0].sum(),'bottom':a[-1].sum(),'left':a[:,0].sum(),'right':a[:,-1].sum(),
            'centy':float((rr*a).sum()/n-(h-1)/2),'centx':float((cc*a).sum()/n-(w-1)/2),
            'connected':None}
D=[describe(rows) for _,rows,_ in ex_shapes]
# one-dimensional feature candidates
keys=['h','w','n','empty','area','dens','rows_nonzero','cols_nonzero','top','bottom','left','right','centy','centx']
for k in keys:
  vals=[d[k] for d in D]; labs=[e[2] for e in ex_shapes]
  thresholds=sorted(set(vals))
  best=[]
  for t in thresholds:
    for op in ('<=','>'):
      preds=[v<=t if op=='<=' else v>t for v in vals]
      acc=sum((1 if p else -1)==y for p,y in zip(preds,labs))/len(labs)
      best.append((acc,op,t))
  m=max(best)
  if m[0]>.68: print(k,m)

